// Bundle src/*.js into dist/bundle.js, checking each file parses and its requires resolve.
const fs = require('fs'); const path = require('path');
fs.mkdirSync('dist', { recursive: true });
let out = ''; let n = 0;
for (const f of fs.readdirSync('src').sort()) {
  const p = path.join('src', f); const text = fs.readFileSync(p, 'utf8');
  for (const m of text.matchAll(/require\('\.\/([\w.-]+)'\)/g)) {
    if (!fs.existsSync(path.join('src', m[1]))) { console.error(`error: ${p}: cannot resolve './${m[1]}'`); console.error('Build failed with 1 error.'); process.exit(1); }
  }
  out += `// ${f}\n${text}\n`; n++;
}
fs.writeFileSync('dist/bundle.js', out);
console.log(`Built dist/bundle.js from ${n} files (${Buffer.byteLength(out)} bytes).`);
